namespace optiling {

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Shapes
    const gert::Shape* x_shape = context->GetInputShape(0);      // [B, K]
    const gert::Shape* w_shape = context->GetInputShape(1);      // [N, K]
    if (x_shape->GetOriginShape().GetDimNum() != 2 || w_shape->GetOriginShape().GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }
    int64_t B = x_shape->GetOriginShape().GetDim(0);
    int64_t K = x_shape->GetOriginShape().GetDim(1);
    int64_t N = w_shape->GetOriginShape().GetDim(0);
    // Build matmul tiling (multi-core)
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    matmul_tiling::MultiCoreMatmulTiling tiling(ascendcPlatform);
    tiling.SetDim(1);
    tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                    matmul_tiling::DataType::DT_FLOAT);
    tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                    matmul_tiling::DataType::DT_FLOAT);
    tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                    matmul_tiling::DataType::DT_FLOAT);
    tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND,
                       matmul_tiling::DataType::DT_FLOAT);
    tiling.SetShape(static_cast<int32_t>(B), static_cast<int32_t>(N), static_cast<int32_t>(K));
    tiling.SetSingleShape(static_cast<int32_t>(B), static_cast<int32_t>(N), static_cast<int32_t>(K));
    tiling.SetOrgShape(static_cast<int32_t>(B), static_cast<int32_t>(N), static_cast<int32_t>(K));
    tiling.SetBias(true);
    tiling.SetBufferSpace(-1, -1, -1);

    optiling::TCubeTiling tilingData;
    int ret = tiling.GetTiling(tilingData);
    if (ret != 0) {
        return ge::GRAPH_FAILED;
    }

    int32_t coreNum = tiling.GetCoreNum();
    context->SetBlockDim(static_cast<uint32_t>(coreNum));

    // Serialize tiling
    auto raw = context->GetRawTilingData();
    if (raw->GetCapacity() < sizeof(tilingData)) {
        return ge::GRAPH_FAILED;
    }
    std::memcpy(raw->GetData(), &tilingData, sizeof(tilingData));
    raw->SetDataSize(sizeof(tilingData));

    // No workspace required
    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;

    return ge::GRAPH_SUCCESS;
}

} // namespace optiling

